  .input(signoffContext)
  .output(z.object({ paged: z.boolean() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['pager', 'notify', 'finance-deputy', `Sign-off pending: ${input.title} ($${input.amountUsd})`]);
    return { paged: result.code === 0 };
  });

